typedef long long ll;

int main(void) {
    char s[200005];
    ll K;
    if (scanf("%s %lld", s, &K) != 2) return 0;

    int n = (int)strlen(s);

    // Check if all characters are the same
    int all_same = 1;
    for (int i = 1; i < n; i++) {
        if (s[i] != s[0]) {
            all_same = 0;
            break;
        }
    }

    if (all_same) {
        // Entire T is one run of length n*K
        printf("%lld\n", (ll)n * K / 2);
        return 0;
    }

    // Count operations for one copy of S:
    // sum over runs of floor(len/2)
    ll one = 0;
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && s[j] == s[i]) j++;
        one += (j - i) / 2;
        i = j;
    }

    // If first and last characters differ, copies do not interact
    if (s[0] != s[n - 1]) {
        printf("%lld\n", one * K);
        return 0;
    }

    // First and last chars are the same, so boundary runs merge
    int pref = 0;
    while (pref < n && s[pref] == s[0]) pref++;

    int suff = 0;
    while (suff < n && s[n - 1 - suff] == s[n - 1]) suff++;

    // Extra gain per boundary when merging suffix+prefix
    ll extra = (pref + suff) / 2 - pref / 2 - suff / 2;

    ll ans = one * K + extra * (K - 1);
    printf("%lld\n", ans);

    return 0;
}

