        String S = sc.next();
        int K = sc.nextInt();
        int n = S.length();

        // If the string has length 1, special case:
        if (n == 1) {
            System.out.println(K / 2);
            return;
        }

        // Count changes inside one copy
        int changesInside = 0;
        StringBuilder sb = new StringBuilder(S);
        for (int i = 1; i < n; i++) {
            if (sb.charAt(i) == sb.charAt(i - 1)) {
                changesInside++;
                // Change this character to something different
                char newChar = 'a';
                while (newChar == sb.charAt(i) || (i + 1 < n && newChar == sb.charAt(i + 1))) {
                    newChar++;
                }
                sb.setCharAt(i, newChar);
            }
        }

        long totalChanges = (long) changesInside * K;

        // Handle junctions between copies
        if (S.charAt(0) == S.charAt(n - 1)) {
            // Check if first or last char was changed in the interior fix
            boolean firstChanged = (S.charAt(0) != sb.charAt(0));
            boolean lastChanged = (S.charAt(n - 1) != sb.charAt(n - 1));

            if (!firstChanged && !lastChanged) {
                totalChanges += (K - 1);
            } else {
                // If both changed, junction cost zero; if only one changed, count junctions
                // Actually if one of them changed, that breaks the equality at the junction
                // No extra cost needed
            }
        }

        // Edge case: if all characters in S are same, our interior fix might not be optimal for K>1
        // We need to re-evaluate: For all equal, best is ceil(K*n/2) changes, but our method may overcount.
        // Let's handle that specific case.
        boolean allSame = true;
        for (int i = 1; i < n; i++) {
            if (S.charAt(i) != S.charAt(0)) {
                allSame = false;
                break;
            }
        }
        if (allSame) {
            // For a string of all same characters, optimal is ceil(K * n / 2)
            long total = (long) K * n;
            System.out.println((total + 1) / 2);
            return;
        }

        System.out.println(totalChanges);
    }
