        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int K = sc.nextInt();
        int n = S.length();

        if (n == 1) {
            // T has K chars all same, need K/2 changes? No: "aaaa" -> change every other
            // Actually for single char repeated K times, need ceil((K-1)/2)... 
            // "a" repeated K times: need floor(K/2) changes
            System.out.println(K / 2);
            return;
        }

        int INF = 1000000;
        // dp[c] = min ops for position i with char c
        int[] dp = new int[26];
        // Initialize for position 0
        for (int c = 0; c < 26; c++) {
            dp[c] = (S.charAt(0) - 'a' == c) ? 0 : 1;
        }

        for (int i = 1; i < n; i++) {
            int[] ndp = new int[26];
            int orig = S.charAt(i) - 'a';
            for (int c = 0; c < 26; c++) {
                int cost = (orig == c) ? 0 : 1;
                int best = INF;
                for (int pc = 0; pc < 26; pc++) {
                    if (pc != c) best = Math.min(best, dp[pc]);
                }
                ndp[c] = best + cost;
            }
            dp = ndp;
        }

        if (K == 1) {
            System.out.println(Arrays.stream(dp).min().getAsInt());
        } else {
            // Need s[0] != s[n-1], fix first char and run DP
            int ans = INF;
            for (int c0 = 0; c0 < 26; c0++) {
                int[] dpC = new int[26];
                int orig0 = S.charAt(0) - 'a';
                Arrays.fill(dpC, INF);
                dpC[c0] = (orig0 == c0) ? 0 : 1;
                for (int i = 1; i < n; i++) {
                    int[] ndp = new int[26];
                    int orig = S.charAt(i) - 'a';
                    for (int c = 0; c < 26; c++) {
                        int cost = (orig == c) ? 0 : 1;
                        int best = INF;
                        for (int pc = 0; pc < 26; pc++) {
                            if (pc != c && dpC[pc] < INF) best = Math.min(best, dpC[pc]);
                        }
                        ndp[c] = (best == INF) ? INF : best + cost;
                    }
                    dpC = ndp;
                }
                for (int cn = 0; cn < 26; cn++) {
                    if (cn != c0) ans = Math.min(ans, dpC[cn]);
                }
            }
            System.out.println(ans);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String s = fs.next();
        long k = fs.nextLong();

        int n = s.length();

        // If all characters are the same:
        // For length n*k, answer is floor((n*k)/2)
        boolean allSame = true;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) != s.charAt(0)) {
                allSame = false;
                break;
            }
        }
        if (allSame) {
            System.out.println((long) n * k / 2);
            return;
        }

        // Count operations for one copy
        long one = count(s);

        // If first and last differ, copies do not interact across boundaries
        if (s.charAt(0) != s.charAt(n - 1)) {
            System.out.println(one * k);
            return;
        }

        // First and last are same, so boundaries may merge runs.
        int prefix = 1;
        while (prefix < n && s.charAt(prefix) == s.charAt(0)) prefix++;

        int suffix = 1;
        while (suffix < n && s.charAt(n - 1 - suffix) == s.charAt(n - 1)) suffix++;

        // Extra contribution per boundary
        long extraPerBoundary = (prefix + suffix) / 2 - prefix / 2 - suffix / 2;

        long ans = one * k + extraPerBoundary * (k - 1);
        System.out.println(ans);
    }

    static long count(String s) {
        long res = 0;
        int n = s.length();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            res += (j - i) / 2;
            i = j;
        }
        return res;
    }

    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private String[] tokens = new String[0];
        private int idx = 0;

        String next() throws IOException {
            while (idx >= tokens.length) {
                String line = br.readLine();
                if (line == null) return null;
                tokens = line.trim().split("\\s+");
                idx = 0;
            }
            return tokens[idx++];
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

